const $=s=>document.querySelector(s), E=Engine;let timer=null,pending=null,session=0,active=false,state=null;
const games=[{id:'lights',name:'불빛 뒤집기',cover:'assets/lights-v2.svg',tag:'자유 모드 · 난이도별 도전',desc:'불을 모두 끄세요. 자유 모드와 난이도별 25회 도전을 선택할 수 있습니다.',rules:['누른 칸과 상하좌우의 불빛이 함께 바뀝니다. 16칸을 모두 끄면 성공입니다.','자유 모드는 횟수 제한이 없습니다. 25회 도전은 쉬움·보통·어려움을 고릅니다.','실제 최소 풀이가 쉬움 2~3회, 보통 4~5회, 어려움 6~7회인 문제를 제공합니다. 모든 도전의 제한은 25회입니다.','진행 중 모드·난이도를 바꾸면 확인 후 새 문제로 시작합니다. 새로고침하면 같은 진행을 복구합니다.','기존 불빛 뒤집기와 리버스 타일 기록을 보존하고 새 모드·난이도별 기록은 따로 비교합니다.']},{id:'baseball',name:'숫자야구',cover:'assets/baseball-v2.svg',tag:'0~9 · 3/4자리 · 10회',desc:'스트라이크와 볼을 단서로 숨겨진 숫자를 찾아보세요.',rules:['시간제한 없는 그림 연습에서 S·B·아웃과 3자리·4자리 입력을 익힐 수 있습니다. 연습은 실제 진행과 기록에 영향을 주지 않습니다.','중복 없는 0~9 숫자를 3자리 또는 4자리로 맞힙니다. 0으로 시작해도 됩니다.','숫자와 위치가 모두 맞으면 스트라이크(S), 숫자만 맞으면 볼(B)입니다. 0S 0B는 아웃입니다.','제한시간 없이 10회 도전합니다. 잘못된 입력과 이미 시도한 숫자는 횟수를 쓰지 않습니다.','모든 자리가 스트라이크이면 승리합니다. 10회 안에 못 맞히면 정답을 공개합니다.','경기 중 다시 시작하면 기록을 저장하지 않습니다. 완료 기록은 자릿수별로 이 브라우저에 저장됩니다.']},{id:'triple',name:'트리플 코드',tag:'논리력 · 추리력',desc:'세 가지 속성 속, 단 하나의 조합을 찾아보세요.',rules:['시간제한 없는 그림 연습에서는 조건별 비교를 연습할 수 있습니다. 연습은 실제 도전의 점수와 기록에 포함되지 않습니다.','3×3의 9장 중 목표에 맞는 카드 3장을 선택합니다.','모양·개수·무늬는 속성별로 모두 같거나 모두 달라야 합니다. 각 문제의 목표를 확인하세요.','6라운드, 라운드당 40초. 정답은 100점 + 남은 초입니다.','오답은 누적 점수에서 30점 감점(최저 0점). 3회 오답 또는 시간초과 라운드는 0점입니다.']},{id:'memory',name:'기억의 짝',tag:'기억력 · 집중력',desc:'뒤집고 기억하고, 여덟 쌍의 연결을 완성하세요.',rules:['그림 연습은 시간·오답 제한 없이 짝 찾기를 배웁니다. 서로 다른 두 카드는 직접 닫고, 실제 진행과 기록에는 영향을 주지 않습니다.','4×4 카드 16장, 총 8쌍을 찾습니다.','120초 안에 모든 짝을 찾으면 완료됩니다.','다른 두 카드는 1.2초 후 닫히며, 판정 중에는 입력할 수 없습니다.','점수 = max(0, 1000 − 5×경과초 − 40×오답). 미완료 경기는 최고점에서 제외합니다.']}];
const recordGames=[...games,{id:'nine',name:'나인 블러프'}];
$('#game-list').innerHTML=games.map(g=>`<article class="game-card ${g.id}"><button class="game-launch" onclick="launchGame('${g.id}')" aria-label="${g.name} 바로 플레이"><span class="card-cover"><img src="${g.cover||`assets/${g.id}-v2.png`}" alt="" width="326" height="130"></span><span class="card-body"><strong class="game-name">${g.name}</strong><span class="tags">${g.tag.split(' · ').map(t=>`<span>${t}</span>`).join('')}<span>싱글 1인</span></span><span class="card-play" aria-hidden="true">바로 플레이 →</span></span></button><button class="card-rules" onclick="showGameRules('${g.id}')" aria-label="${g.name} 방법 보기">방법 보기</button></article>`).join('');
function cleanup(){$('#active-rules').hidden=true;Sound.stop();clearInterval(timer);clearTimeout(pending);timer=pending=null;session++;active=false}
function openModal(){if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){if(active&&gameHasProgress()){askGameChange('진행을 저장하고 게임 목록으로 돌아갈까요? 같은 게임을 누르면 이어할 수 있습니다.',()=>{cleanup();$('#modal').close()});return}cleanup();$('#modal').close()}
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
function info(title,message){cleanup();openModal();$('#content').innerHTML=`<h2>${title}</h2><p>${message}</p><button onclick="closeModal()">확인</button>`}
function tutorial(id){showGameRules(id)}
function showGameRules(id){const g=games.find(g=>g.id===id);if(!g)return;Sound.play('select');$('#game-rules-content').innerHTML=`<h2 id="rules-heading">${g.name} · 방법 보기</h2><p>${g.desc}</p><ol class="rules">${g.rules.map(x=>`<li>${x}</li>`).join('')}</ol>${active?'<p class="note">설명을 읽는 동안 제한시간이 멈춥니다. 닫으면 같은 게임을 계속합니다.</p>':`<button class="primary" onclick="launchGame('${id}')">바로 플레이 →</button>`}`;if(!$('#game-rules').open)$('#game-rules').showModal()}
function launchGame(id){if(id==='lights'&&!active){location.href='lights.html';return}if(!games.some(g=>g.id===id)||active)return;if($('#game-rules').open)$('#game-rules').close();start(id)}
function focusGames(event){event?.preventDefault();$('#game-navigation').textContent='게임 목록입니다. 원하는 게임을 누르면 바로 시작해요.';history.replaceState(null,'','#games');$('#games').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('#games-heading').focus({preventScroll:true})}
let gameChangeAction=null;
function askGameChange(message,action){if($('#confirm-dialog').open)return;gameChangeAction=action;$('#confirm-message').textContent=message;$('#confirm-cancel').textContent=active?'계속 플레이':'취소';$('#confirm-accept').textContent=active?'변경하기':'기록 지우기';$('#confirm-dialog').showModal()}
function cancelGameChange(){gameChangeAction=null;$('#confirm-dialog').close()}
function acceptGameChange(){const action=gameChangeAction;gameChangeAction=null;$('#confirm-dialog').close();if(action)action()}
$('#confirm-dialog').addEventListener('cancel',()=>{gameChangeAction=null});
function gameHasProgress(){if(!active)return false;if(state.id==='baseball')return state.game.attempts.length>0||!!$('#baseball-guess')?.value;if(state.id==='lights')return state.game.moves>0;if(state.id==='triple')return state.round>1||state.selection.length>0||state.wrong>0;return state.open.length>0||state.matched.length>0||state.errors>0}

function start(id,length=3){if(active||!games.some(g=>g.id===id))return;cleanup();openModal();$('#modal').scrollTop=0;Sound.play('select');active=true;$('#active-rules').hidden=false;if(id==='lights'){state={id,game:E.createLights()};lightsRender()}else if(id==='baseball'){state={id,game:E.createBaseball(length)};baseballRender()}else if(id==='triple'){state={id,round:0,score:0,errors:0,log:[]};tripleRound()}else if(id==='memory'){state={id,deck:E.shuffle([...Array(8).keys(),...Array(8).keys()]),open:[],matched:[],errors:0,locked:false,start:Date.now()};memoryRender();clock(120,()=>finishMemory(false),()=>{$('#clock').textContent=remaining()})}}
function clock(seconds,expired,tick){clearInterval(timer);state.deadline=Date.now()+seconds*1000;let sid=session;timer=setInterval(()=>{if(sid!==session)return;tick();if(Date.now()>=state.deadline){clearInterval(timer);expired()}},100)}
function remaining(){return Math.max(0,Math.ceil((state.deadline-Date.now())/1000))}
function later(fn,ms=1200){let sid=session;pending=setTimeout(()=>{if(sid===session)fn()},ms)}
function tripleRound(){if(state.round===6){finish('트리플 코드',state.score,'6라운드 완료',true,state.log,state.score>0?'win':'lose');return}state.round++;state.wrong=0;state.selection=[];state.puzzle=E.puzzle();state.locked=false;tripleRender();clock(40,()=>tripleEnd(false,'시간초과'),()=>{$('#clock').textContent=remaining()})}
function tripleRender(){let labels=['모양','개수','무늬'];$('#content').innerHTML=`<h2>트리플 코드</h2><button type="button" class="practice-entry" onclick="window.TriplePractice?.open()">시간제한 없는 그림 연습</button><div class="status"><span>라운드 <strong>${state.round}/6</strong></span><span>남은 시간 <strong id="clock">40</strong>초</span><span>점수 <strong id="score">${state.score}</strong></span></div><div class="rules">목표: ${labels.map((x,i)=>`<b>${x}</b> ${state.puzzle.target[i]?'모두 같음':'모두 다름'}`).join(' · ')}</div><div class="board triple">${state.puzzle.cards.map((c,i)=>`<button class="tile" aria-label="${i+1}번 ${['원','삼각형','사각형'][c[0]]} ${c[1]+1}개 ${['빈 무늬','줄 무늬','채운 무늬'][c[2]]}" aria-pressed="false" onclick="selectTriple(${i})"><span class="triple-symbols" style="color:${['#246cf0','#8952d8','#12877e'][c[0]]}">${Array.from({length:c[1]+1},(_,j)=>tripleSymbol(c, i+'-'+j)).join('')}<small class="pattern">${['빈 무늬','줄 무늬','채운 무늬'][c[2]]}</small></span></button>`).join('')}</div><p class="message" id="message" role="status" aria-live="polite">카드 3장을 선택하세요.</p><button class="primary" id="submit" onclick="submitTriple()" disabled>정답 제출</button>`;}

function selectTriple(i){if(state.locked)return;if(Date.now()>=state.deadline){tripleEnd(false,'시간초과');return}let a=state.selection;if(a.includes(i))a.splice(a.indexOf(i),1);else if(a.length<3)a.push(i);document.querySelectorAll('.triple .tile').forEach((el,j)=>{el.classList.toggle('selected',a.includes(j));el.setAttribute('aria-pressed',String(a.includes(j)))});$('#submit').disabled=a.length!==3;Sound.play('select')}
function submitTriple(){if(state.locked||state.selection.length!==3)return;if(Date.now()>=state.deadline){tripleEnd(false,'시간초과');return}if(E.matches(state.puzzle.cards,state.selection,state.puzzle.target))tripleEnd(true,'정답');else{state.errors++;state.wrong++;state.score=Math.max(0,state.score-30);$('#score').textContent=state.score;$('#message').textContent=`오답입니다. −30점 · ${state.wrong}/3회`;if(state.wrong===3)tripleEnd(false,'3회 오답');else Sound.play('wrong')}}
function tripleEnd(correct,reason){if(state.locked)return;state.locked=true;Sound.play(correct?'correct':'wrong');clearInterval(timer);let earned=correct?E.tripleScore(remaining()):0;state.score+=earned;state.log.push(`${state.round}라운드 · ${reason} · +${earned}점`);$('#score').textContent=state.score;$('#message').textContent=`${reason} · +${earned}점. 다음 라운드로 이동합니다.`;$('#submit').disabled=true;state.puzzle.answer.forEach(i=>document.querySelectorAll('.triple .tile')[i].classList.add('selected'));later(tripleRound,1500)}
const symbols=['🍎','🍋','🍇','🍒','🥝','🍊','🍓','🫐'];
function memoryRender(){ $('#content').innerHTML=`<h2>기억의 짝</h2><button type="button" class="practice-entry" onclick="window.PopupPractice?.open('memory')">시간제한 없는 그림 연습</button><div class="status"><span>남은 시간 <strong id="clock">120</strong>초</span><span>찾은 짝 <strong id="pairs">0</strong>/8</span><span>오답 <strong id="errors">0</strong></span></div><div class="board memory">${state.deck.map((_,i)=>`<button class="tile" aria-label="${i+1}번 카드 뒤집기" onclick="flip(${i})">?</button>`).join('')}</div><p class="message" id="message" role="status" aria-live="polite">두 장씩 뒤집어 같은 과일을 찾아보세요.</p>`}
function flip(i){if(state.locked||state.matched.includes(i)||state.open.includes(i))return;if(Date.now()>=state.deadline){finishMemory(false);return}let el=document.querySelectorAll('.memory .tile')[i];el.textContent=symbols[state.deck[i]];el.classList.add('open');el.setAttribute('aria-label',`${i+1}번 ${symbols[state.deck[i]]}`);state.open.push(i);Sound.play('select');if(state.open.length===2){state.locked=true;let [a,b]=state.open;if(state.deck[a]===state.deck[b]){state.matched.push(a,b);[a,b].forEach(j=>{let c=document.querySelectorAll('.memory .tile')[j];c.classList.add('matched');c.disabled=true});$('#pairs').textContent=state.matched.length/2;state.open=[];state.locked=false;if(state.matched.length===16)finishMemory(true);else Sound.play('correct')}else{Sound.play('wrong');state.errors++;$('#errors').textContent=state.errors;later(()=>{[a,b].forEach(j=>{let c=document.querySelectorAll('.memory .tile')[j];c.textContent='?';c.classList.remove('open');c.setAttribute('aria-label',`${j+1}번 카드 뒤집기`)});state.open=[];state.locked=false},1200)}}}
function finishMemory(complete){if(!active)return;let elapsed=Math.min(120,Math.floor((Date.now()-state.start)/1000));finish('기억의 짝',complete?E.memoryScore(elapsed,state.errors):0,complete?'8쌍 모두 찾았어요!':'시간초과 · 미완료',complete,[`경과 ${elapsed}초 · 오답 ${state.errors}회`,`찾은 짝 ${state.matched.length/2}/8`],complete?'win':'lose')}
function readRecords(){try{let a=JSON.parse(localStorage.getItem('panludiq.records.v1')||'[]');return Array.isArray(a)?a.filter(x=>recordGames.some(g=>g.id===x.id)&&Number.isFinite(x.score)&&typeof x.time==='string').slice(0,100):[]}catch{return []}}
function finish(name,score,message,complete,log,outcome='win'){let id=state.id;cleanup();Sound.play(outcome);let saved=true;try{let rows=readRecords();rows.unshift({id,score,complete,message,time:new Date().toISOString()});localStorage.setItem('panludiq.records.v1',JSON.stringify(rows.slice(0,100)))}catch{saved=false}$('#content').innerHTML=`<div class="result"><p class="eyebrow">GAME RESULT</p><h2>${name} · ${message}</h2><div class="score">${score}<small>${id==='nine'?'승점':'점'}</small></div><p class="note">${saved?'이 브라우저에 기록을 저장했습니다.':'브라우저 저장 공간을 사용할 수 없어 기록을 저장하지 못했습니다.'}</p></div><div class="rules">${log.map(x=>`<div>${x}</div>`).join('')}</div><div class="actions"><button class="primary" onclick="launchGame('${id}')">다시 플레이</button><button onclick="showRecords()">내 기록</button><button onclick="closeModal()">홈으로</button></div>`}
function showRecords(){cleanup();Sound.play('select');openModal();let rows=readRecords(),visibleRows=rows.filter(r=>r.id!=='nine');$('#content').innerHTML=`<h2>내 기록</h2><p class="note">이 브라우저의 경기만 표시합니다. 공용 랭킹과 계정 동기화는 준비 중입니다.</p><div class="rules">${games.filter(g=>g.id==='triple'||g.id==='memory').map(g=>{let scores=rows.filter(r=>r.id===g.id&&r.complete).map(r=>r.score);return `<div>${g.name} · 최고 ${scores.length?Math.max(...scores)+(g.id==='nine'?'승점':'점'):'기록 없음'}</div>`}).join('')}</div>${baseballRecordsMarkup()}${lightsRecordsMarkup()}<h3>싱글게임 공통 기록</h3><a class="suite-record-link" href="code-breaker.html?records=1">싱글게임 5종 기록 보기 →</a><h3>최근 점수 경기</h3>${visibleRows.length?visibleRows.slice(0,20).map(r=>`<div class="record-row"><span>${recordGames.find(g=>g.id===r.id).name}<small><br>${new Date(r.time).toLocaleString('ko-KR')}</small></span><strong>${r.score}${r.id==='nine'?'승점':'점'}${r.complete?'':' · 미완료'}</strong></div>`).join(''):'<div class="empty">아직 점수 경기 기록이 없습니다.</div>'}<button style="margin-top:20px" onclick="clearRecords()" ${visibleRows.length||readBaseballRecords().length||readLightsRecords().length?'':'disabled'}>표시된 기록 지우기</button>`}
function clearRecords(){askGameChange('현재 표시된 기록을 지울까요? 보관 중인 게임 기록은 유지됩니다.',()=>{try{const preserved=readRecords().filter(r=>r.id==='nine');if(preserved.length)localStorage.setItem('panludiq.records.v1',JSON.stringify(preserved));else localStorage.removeItem('panludiq.records.v1');localStorage.removeItem('panludiq.baseball.v1');localStorage.removeItem('panludiq.lights.v1');showRecords()}catch{info('삭제 실패','브라우저 저장소 접근이 제한되어 있습니다.')}})}


function baseballRender(){const g=state.game;$('#content').innerHTML=`<p class="eyebrow">BULLS AND COWS · SOLO</p><h2>숫자야구</h2><button type="button" class="practice-entry" onclick="window.PopupPractice?.open('baseball')">시간제한 없는 그림 연습</button><label class="baseball-mode">자릿수 <select id="baseball-length" aria-label="숫자야구 자릿수" onchange="changeBaseballLength(this.value)"><option value="3" ${g.length===3?'selected':''}>3자리</option><option value="4" ${g.length===4?'selected':''}>4자리</option></select></label><div class="status"><span>도전 <strong id="baseball-count">${g.attempts.length}/10</strong></span><span>중복 없음 · 첫 자리 0 가능</span></div><p class="note">숫자·위치 일치 = S · 숫자만 일치 = B · 0S 0B = 아웃<br>시간제한 없음 · 중복 입력과 잘못된 입력은 횟수 차감 없음</p><form id="baseball-form" novalidate><label for="baseball-guess">추리한 숫자 ${g.length}자리</label><div class="baseball-entry"><input id="baseball-guess" type="text" inputmode="numeric" autocomplete="off" spellcheck="false" maxlength="${g.length}" pattern="[0-9]{${g.length}}" aria-describedby="baseball-message" placeholder="${g.length===3?'예: 037':'예: 0378'}"><button class="primary" type="submit">던지기 →</button></div><p class="message" id="baseball-message" role="status" aria-live="polite">첫 번째 숫자를 던져보세요.</p></form><section class="baseball-history" aria-label="숫자야구 시도 기록"><h3>시도 기록</h3><div id="baseball-history"><p class="note">단서를 모아 정답을 좁혀보세요.</p></div></section><div class="actions baseball-actions"><button type="button" onclick="restartBaseball()">다시 시작</button><button type="button" onclick="showGameRules('baseball')">방법 보기</button></div>`;$('#baseball-form').addEventListener('submit',submitBaseball);$('#baseball-guess').focus()}
function baseballHistory(){return '<ol class="baseball-attempts">'+state.game.attempts.map((a,i)=>`<li><span class="attempt-no">${i+1}회</span><strong class="baseball-number">${a.guess}</strong><span class="baseball-clue"><b>${a.strikes} S</b><span>${a.balls} B</span>${a.strikes+a.balls===0?'<small>아웃</small>':''}</span></li>`).join('')+'</ol>'}
function submitBaseball(event){event.preventDefault();if(!active||state.id!=='baseball'||state.game.status!=='playing')return;const input=$('#baseball-guess'),result=E.guessBaseball(state.game,input.value);if(result.error){input.setAttribute('aria-invalid','true');$('#baseball-message').textContent=result.error;Sound.play('wrong');input.focus();return}state.game=result.game;input.removeAttribute('aria-invalid');$('#baseball-count').textContent=state.game.attempts.length+'/10';$('#baseball-history').innerHTML=baseballHistory();if(state.game.status!=='playing'){finishBaseball();return}const last=state.game.attempts.at(-1);$('#baseball-message').textContent=`${last.guess} · ${last.strikes} 스트라이크, ${last.balls} 볼${last.strikes+last.balls===0?' · 아웃':''}. ${10-state.game.attempts.length}회 남았어요.`;Sound.play(last.strikes+last.balls>0?'correct':'wrong');input.value='';input.focus()}
function resetBaseball(length){cleanup();Sound.play('select');active=true;$('#active-rules').hidden=false;state={id:'baseball',game:E.createBaseball(length)};baseballRender()}
function restartBaseball(){if(!active||state.id!=='baseball')return;const length=state.game.length;if(gameHasProgress())askGameChange('새 숫자로 시작할까요? 입력한 숫자와 진행 중인 기록은 저장되지 않습니다.',()=>resetBaseball(length));else resetBaseball(length)}
function changeBaseballLength(value){if(!active||state.id!=='baseball')return;const length=Number(value),previous=state.game.length;if(length!==3&&length!==4)return;$('#baseball-length').value=String(previous);if(length===previous)return;if(gameHasProgress())askGameChange(`${length}자리로 바꿀까요? 입력한 숫자와 진행 중인 기록은 저장되지 않습니다.`,()=>resetBaseball(length));else resetBaseball(length)}

function readBaseballRecords(){try{const rows=JSON.parse(localStorage.getItem('panludiq.baseball.v1')||'[]');return Array.isArray(rows)?rows.filter(r=>(r.length===3||r.length===4)&&Number.isInteger(r.attempts)&&r.attempts>=1&&r.attempts<=10&&typeof r.won==='boolean'&&typeof r.time==='string').slice(0,100):[]}catch{return []}}
function finishBaseball(){const g=state.game,won=g.status==='won',history=baseballHistory();cleanup();Sound.play(won?'win':'lose');let saved=true;try{const rows=readBaseballRecords();rows.unshift({length:g.length,attempts:g.attempts.length,won,time:new Date().toISOString()});localStorage.setItem('panludiq.baseball.v1',JSON.stringify(rows.slice(0,100)))}catch{saved=false}$('#content').innerHTML=`<div class="result"><p class="eyebrow">BULLS AND COWS · RESULT</p><h2>${won?'스트라이크! 정답을 찾았어요.':'10회 도전 완료 · 다음엔 맞힐 수 있어요.'}</h2><p>${g.length}자리 · ${g.attempts.length}회 도전 · ${won?'승리':'실패'}</p><p>정답 <strong class="baseball-answer">${g.secret}</strong></p><p class="note">${saved?'자릿수별 기록을 이 브라우저에 저장했습니다.':'브라우저 저장이 제한되어 기록을 저장하지 못했습니다.'}</p></div>${history}<div class="actions baseball-actions"><button class="primary" onclick="replayBaseball(${g.length})">같은 자릿수로 다시 도전</button><button onclick="launchGame('baseball')">자릿수 바꾸기</button><button onclick="showRecords()">내 기록</button></div>`}
function replayBaseball(length){if(active)return;resetBaseball(length)}
function baseballRecordsMarkup(){const rows=readBaseballRecords();return '<h3>숫자야구 · 자릿수별 기록</h3><div class="rules">'+[3,4].map(length=>{const matches=rows.filter(r=>r.length===length),wins=matches.filter(r=>r.won);return `<div>${length}자리 · ${wins.length}승 / ${matches.length}경기 · 최소 ${wins.length?Math.min(...wins.map(r=>r.attempts))+'회':'기록 없음'}</div>`}).join('')+'</div>'+rows.slice(0,10).map(r=>`<div class="record-row"><span>숫자야구 ${r.length}자리<small><br>${new Date(r.time).toLocaleString('ko-KR')}</small></span><strong>${r.won?'승리':'실패'} · ${r.attempts}회</strong></div>`).join('')}


function lightsRender(){const g=state.game;$('#content').innerHTML=`<p class="eyebrow">LIGHTS OUT · SOLO</p><h2>불빛 뒤집기</h2><div class="status"><span>이동 <strong id="lights-moves">0</strong>회</span><span>켜진 불 <strong id="lights-count"></strong>/16</span></div><p class="note">누른 칸과 상하좌우가 반전됩니다. 불을 모두 끄면 성공!<br>시간·이동횟수 제한 없음 · 모든 판은 풀 수 있어요.</p><div class="lights-board" role="group" aria-label="4행 4열 불빛 퍼즐">${Array.from({length:16},(_,i)=>`<button type="button" data-light="${i}" onclick="pressLight(${i})"></button>`).join('')}</div><p class="message" id="lights-message" role="status" aria-live="polite">불빛을 하나 눌러 시작해보세요.</p><div class="actions"><button onclick="restartLights()">새 판으로 다시 시작</button></div>`;updateLights()}
function updateLights(){const g=state.game;$('#lights-moves').textContent=g.moves;let count=0;document.querySelectorAll('[data-light]').forEach((button,i)=>{const on=!!(g.board&(1<<i));count+=Number(on);button.classList.toggle('is-on',on);button.setAttribute('aria-pressed',String(on));button.setAttribute('aria-label',`${Math.floor(i/4)+1}행 ${i%4+1}열 · ${on?'켜짐':'꺼짐'} · 누르면 주변과 반전`);button.innerHTML=on?'<span aria-hidden="true">☀</span>':'<span aria-hidden="true">·</span>'});$('#lights-count').textContent=count;return count}
function pressLight(index){if(!active||state.id!=='lights'||state.game.status!=='playing')return;state.game=E.pressLights(state.game,index);const count=updateLights();if(state.game.status==='won'){finishLights();return}Sound.play('select');$('#lights-message').textContent=`${state.game.moves}회 이동 · 불빛 ${count}개가 켜져 있어요.`}
function resetLights(){cleanup();Sound.play('select');active=true;$('#active-rules').hidden=false;state={id:'lights',game:E.createLights()};lightsRender()}
function restartLights(){if(!active||state.id!=='lights')return;if(state.game.moves)askGameChange('현재 판을 끝내고 새 퍼즐로 시작할까요? 진행 중인 기록은 저장되지 않습니다.',resetLights);else resetLights()}

function readLightsRecords(){try{const rows=JSON.parse(localStorage.getItem('panludiq.lights.v1')||'[]');return Array.isArray(rows)?rows.filter(r=>Number.isInteger(r.moves)&&r.moves>0&&typeof r.time==='string').slice(0,100):[]}catch{return []}}
function finishLights(){const moves=state.game.moves;cleanup();Sound.play('win');let saved=true;try{const rows=readLightsRecords();rows.unshift({moves,time:new Date().toISOString()});localStorage.setItem('panludiq.lights.v1',JSON.stringify(rows.slice(0,100)))}catch{saved=false}$('#content').innerHTML=`<div class="result"><p class="eyebrow">LIGHTS OUT · RESULT</p><h2>모든 불을 껐어요!</h2><div class="score">${moves}<small>회 이동</small></div><p class="note">${saved?'이 브라우저에 성공 기록을 저장했습니다.':'브라우저 저장이 제한되어 기록을 저장하지 못했습니다.'}</p></div><div class="actions baseball-actions"><button class="primary" onclick="replayLights()">새 퍼즐 도전</button><button onclick="showRecords()">내 기록</button><button onclick="closeModal()">홈으로</button></div>`}
function replayLights(){if(active)return;resetLights()}
function lightsRecordsMarkup(){const rows=readLightsRecords();return '<h3>불빛 뒤집기 · 이전 자유 모드 기록</h3><div class="rules">'+(rows.length?`${rows.length}회 성공 · 최소 ${Math.min(...rows.map(r=>r.moves))}회 이동`:'아직 성공 기록이 없습니다.')+'</div>'+rows.slice(0,5).map(r=>`<div class="record-row"><span>불빛 뒤집기<small><br>${new Date(r.time).toLocaleString('ko-KR')}</small></span><strong>성공 · ${r.moves}회 이동</strong></div>`).join('')}

function tripleSymbol(c,key){const id='pattern-'+key;const shape=c[0]===0?'<circle cx="16" cy="16" r="12"/>':c[0]===1?'<path d="M16 3L30 29H2Z"/>':'<rect x="4" y="4" width="24" height="24" rx="2"/>';return `<svg class="triple-symbol" aria-hidden="true" viewBox="0 0 32 32"><defs><pattern id="${id}" patternUnits="userSpaceOnUse" width="6" height="6" patternTransform="rotate(35)"><rect width="2" height="6" fill="currentColor"/></pattern></defs><g fill="${c[2]===0?'none':c[2]===1?'url(#'+id+')':'currentColor'}" stroke="currentColor" stroke-width="1.8">${shape}</g></svg>`}
